; ---------------------------------------------------------------
; void __near__ game_hasee_bounce (void)
; ---------------------------------------------------------------

.segment	"CODE"

.proc	_game_hasee_bounce: near

.segment	"CODE"

;
; HASEE_RESET_PLAYER_FLAGS_START_FRAME();
;
	lda     _player_flags2
	and     #$FE
	sta     _player_flags2
;
; pad1 = pad_poll(0); // read the first controller
;
	lda     #$00
	jsr     _pad_poll
	sta     _pad1
;
; pad1_new = get_pad_new(0);
;
	lda     #$00
	jsr     _get_pad_new
	sta     _pad1_new
;
; pad2 = pad_poll(1); // Will only be used in 2 Player games
;
	lda     #$01
	jsr     _pad_poll
	sta     _pad2
;
; pad2_new = get_pad_new(1); // Or maybe we just call a second function that lets the grounded hasee move only in 2p
;
	lda     #$01
	jsr     _get_pad_new
	sta     _pad2_new
;
; ppu_wait_nmi(); // wait till beginning of the frame
;
	jsr     _ppu_wait_nmi
;
; clear_vram_buffer();
;
	jsr     _clear_vram_buffer
;
; hasee_singleplayer_movement();
;
	jsr     _hasee_singleplayer_movement
;
; hasee_draw_sprites();
;
	jsr     _hasee_draw_sprites
;
; if (HASEE_SCORE_CHANGED_THIS_FRAME) { hasee_update_score(); }
;
	lda     _player_flags2
	and     #$01
	beq     L0500
	jsr     _hasee_update_score
;
; --game_timer;
;
L0500:	lda     _pseudo_scroll_y
	sec
	sbc     #$01
	sta     _pseudo_scroll_y
	bcs     L0505
	dec     _pseudo_scroll_y+1
;
; if (game_timer == 0) {
;
L0505:	lda     _pseudo_scroll_y
	ldx     _pseudo_scroll_y+1
	cpx     #$00
	bne     L0508
	cmp     #$00
L0508:	jsr     booleq
;
; if (pad1 & PAD_B) {
;
	lda     _pad1
	and     #$40
	beq     L0509
;
; pal_fade_to(4, 0);
;
	lda     #$04
	jsr     pusha
	txa
	jsr     _pal_fade_to
;
; menu = MENU_HASEE_BOUNCE;
;
	lda     #$06
	sta     _menu
;
; switch_menu();
;
	jsr     _switch_menu
;
; pal_bright(4);
;
	lda     #$04
	jmp     _pal_bright
;
; }
;
L0509:	rts

.endproc

; ---------------------------------------------------------------
; void __near__ begin_hasee_bounce (void)
; ---------------------------------------------------------------

.segment	"CODE"

.proc	_begin_hasee_bounce: near

.segment	"CODE"

;
; pal_fade_to(4, 0);
;
	lda     #$04
	jsr     pusha
	lda     #$00
	jsr     _pal_fade_to
;
; ppu_off();
;
	jsr     _ppu_off
;
; clear_screen();
;
	jsr     _clear_screen
;
; clear_vram_buffer();
;
	jsr     _clear_vram_buffer
;
; oam_clear();
;
	jsr     _oam_clear
;
; game_timer = 6300; // Frames per game (105 seconds * 60 fps)
;
	ldx     #$18
	lda     #$9C
	sta     _pseudo_scroll_y
	stx     _pseudo_scroll_y+1
;
; game_mode = MODE_GAME;
;
	lda     #$01
	sta     _game_mode
;
; player1.velocity_x = 0;
;
	lda     #$00
	sta     _valrigard+4
	sta     _valrigard+4+1
;
; player1.velocity_y = 0;
;
	sta     _valrigard+6
	sta     _valrigard+6+1
;
; player2.velocity_x = 0;
;
	sta     _player2+4
	sta     _player2+4+1
;
; player2.velocity_y = 0;
;
	sta     _player2+6
	sta     _player2+6+1
;
; player2.x = 0x4000;
;
	ldx     #$40
	sta     _player2
	stx     _player2+1
;
; player2.y = ON_BRANCH_STARTING_Y_VALUE;
;
	ldx     #$33
	sta     _player2+2
	stx     _player2+2+1
;
; player1.x = 0xC000;
;
	ldx     #$C0
	sta     _valrigard
	stx     _valrigard+1
;
; player1.y = ON_GROUND_STARTING_Y_VALUE;
;
	ldx     #$D0
	sta     _valrigard+2
	stx     _valrigard+2+1
;
; player_flags = ORANGE_HASEE_ACTIVE | ACTIVE_PLAYER_BRANCH_STATUS;
;
	lda     #$03
	sta     _player_flags
;
; player_flags2 = 0;
;
	lda     #$00
	sta     _player_flags2
;
; score = 0;
;
	sta     _score
	sta     _score+1
;
; set_prg_bank(5);
;
	lda     #$05
	jsr     _set_prg_bank
;
; temppointer = hasee_game_screen;
;
	lda     #<(_hasee_game_screen)
	ldx     #>(_hasee_game_screen)
	sta     _temppointer
	stx     _temppointer+1
;
; LZG_decode(temppointer, cmap);
;
	jsr     pushax
	lda     #<(_cmap)
	ldx     #>(_cmap)
	jsr     _LZG_decode
;
; vram_write(cmap, 32*32);
;
	lda     #<(_cmap)
	ldx     #>(_cmap)
	jsr     pushax
	ldx     #$04
	lda     #$00
	jsr     _vram_write
;
; enemies_count = MAX_TREATS_ONSCREEN;
;
	lda     #$0D
	sta     _enemies_count
;
; calculate_shuffle_array();
;
	jsr     _calculate_shuffle_array
;
; ppu_on_all();
;
	jsr     _ppu_on_all
;
; pal_bright(4);
;
	lda     #$04
	jmp     _pal_bright

.endproc

; ---------------------------------------------------------------
; void __near__ calculate_next_treat (void)
; ---------------------------------------------------------------

.segment	"CODE"

.proc	_calculate_next_treat: near

.segment	"CODE"

;
; temp0 = rand8();
;
	jsr     _rand8
	sta     _temp0
;
; temp4 = TREAT_YELLOW; // Default option
;
	lda     #$00
	sta     _temp4
;
; if (temp0 > 230) { // ~10% (really a little less) of the time...
;
	lda     _temp0
	cmp     #$E7
	bcc     L0757
;
; if (rand8() > 252) { // Need to figure out if this is possible with PRNG
;
	jsr     _rand8
	cmp     #$FD
	bcc     L0756
;
; temp4 = TREAT_MACCY; // Meant to be ~1/10000ish chance
;
	lda     #$0C
;
; } else {
;
	jmp     L0755
;
; temp4 = TREAT_GROSS_DUNG + temp0 & 0b1;
;
L0756:	lda     _temp0
	clc
	adc     #$0D
	and     #$01
;
; } else if (temp0 > 192) { // ~15%ish of the time...
;
	jmp     L0755
L0757:	lda     _temp0
	cmp     #$C1
;
; } else { // The rest (~75%) of the time...
;
	bcc     L0761
;
; }
;
	rts
;
; temp1 = rand8();
;
L0761:	jsr     _rand8
	sta     _temp1
;
; if (temp0 < 20) { // ~1/10th of the time 
;
	lda     _temp0
	cmp     #$14
	bcs     L075F
;
; if (temp1 == 1) {
;
	lda     _temp1
	cmp     #$01
	bne     L0758
;
; temp4 = TREAT_FISH;
;
	lda     #$0A
;
; } else if (temp1 < 5) {
;
	jmp     L0755
L0758:	lda     _temp1
	cmp     #$05
	bcs     L0759
;
; temp4 = TREAT_RAINBOW;
;
	lda     #$09
;
; } else if (temp1 < 21) {
;
	jmp     L0755
L0759:	lda     _temp1
	cmp     #$15
	bcs     L075A
;
; temp4 = TREAT_ICY;
;
	lda     #$08
;
; } else if (temp1 < 45) {
;
	jmp     L0755
L075A:	lda     _temp1
	cmp     #$2D
	bcs     L075B
;
; temp4 = TREAT_FIERY;
;
	lda     #$07
;
; } else if (temp1 < 77) {
;
	jmp     L0755
L075B:	lda     _temp1
	cmp     #$4D
	bcs     L075C
;
; temp4 = TREAT_SPONGE;
;
	lda     #$06
;
; } else if (temp1 < 113) {
;
	jmp     L0755
L075C:	lda     _temp1
	cmp     #$71
	bcs     L075D
;
; temp4 = TREAT_CHECKERED;
;
	lda     #$05
;
; } else if (temp1 < 157) {
;
	jmp     L0755
L075D:	lda     _temp1
	cmp     #$9D
	bcs     L075E
;
; temp4 = TREAT_GOLDEN;
;
	lda     #$04
;
; } else if (temp1 < 213) {
;
	jmp     L0755
L075E:	lda     _temp1
	cmp     #$D5
	bcs     L06FA
;
; temp4 = TREAT_SILVER;
;
	lda     #$03
;
; } else {
;
	jmp     L0755
;
; if (temp1 < 6) {
;
L075F:	lda     _temp1
	cmp     #$06
	bcs     L0760
;
; temp4 = TREAT_GREEN;
;
	lda     #$02
;
; } else if (temp1 < 15) {
;
	jmp     L0755
L0760:	lda     _temp1
	cmp     #$0F
	bcs     L06FA
;
; temp4 = TREAT_BLUE;
;
	lda     #$01
L0755:	sta     _temp4
;
; }
;
L06FA:	rts

.endproc

; ---------------------------------------------------------------
; void __near__ hasee_sprite_collisions (void)
; ---------------------------------------------------------------

.segment	"CODE"

.proc	_hasee_sprite_collisions: near

.segment	"CODE"

;
; hitbox.x = high_byte(player1.x);
;
	lda     _valrigard+1
	sta     _hitbox
